    if _is_tr(text) or re.search(r'\d{1,3}(?:\.\d{3})+(?:,\d+)?|\b\d+,\d{1,2}\b', str(text or '')): return tr_number(text)   # 1.250,00 is Turkish format
    return _en_number(text)

def to_digits(text):
